      const description =
        pick('meta[property="og:description"]', 'content') ||
        pick('meta[name="description"]', 'content') ||
        null;
      const preview =
        abs(pick('meta[property="og:image"]', 'content')) ||
        abs(pick('meta[name="twitter:image"]', 'content')) ||
        null;
