      id                  INTEGER PRIMARY KEY AUTOINCREMENT,
      url                 TEXT NOT NULL,
      normalized_url      TEXT NOT NULL UNIQUE,
      title               TEXT NOT NULL,
      description         TEXT,
      icon_url            TEXT,
      preview_image_url   TEXT,
